#!/bin/sh
# Pix uninstaller for Linux - generated by vexelray-installer. Do not edit by hand; regenerate it.
#
#   uninstall.sh              remove Pix (asks first)
#   uninstall.sh --list       every install recorded in the registry folder
#   uninstall.sh --id ID      remove another install recorded there
#   uninstall.sh --all        remove every install recorded there
#   uninstall.sh --yes        do not ask
#
# Removes exactly what the install record lists: files, menu entries and desktop launchers, the links in
# ~/.local/bin and the file types. Files you added to an install folder are left alone, and so is the folder.

# shellcheck disable=SC2034
{
VI_ID='pix'
VI_NAME='Pix'
VI_PUBLISHER='sibarum'
VI_DESCRIPTION='An image viewer: one picture, as large as the window allows, and the rest of its folder a key press away.'
VI_MANIFEST_URL='https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/pix/manifest.linux.txt'
VI_REGISTRY_DIR='$XDG_DATA_HOME/vexelray-installer/installs'
VI_ISSUES_URL='https://github.com/sibarum/vexelray-dist/issues/new'
}

set -u
vi_tab=$(printf '\t')
VI_LOCKDIR=

vi_say() { printf '%s\n' "$*"; }
vi_warn() { printf 'Warning: %s\n' "$*" >&2; }
vi_die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
vi_cleanup() { [ -n "$VI_LOCKDIR" ] && rm -rf -- "$VI_LOCKDIR"; }

vi_expand() {
    printf '%s\n' "$1" | awk '{
        s = $0; out = ""
        if (s == "~" || substr(s, 1, 2) == "~/") { out = ENVIRON["HOME"]; s = substr(s, 2) }
        while (match(s, /\$\{[A-Za-z_][A-Za-z0-9_]*\}|\$[A-Za-z_][A-Za-z0-9_]*/)) {
            v = substr(s, RSTART, RLENGTH); gsub(/[${}]/, "", v)
            out = out substr(s, 1, RSTART - 1) ENVIRON[v]; s = substr(s, RSTART + RLENGTH)
        }
        print out s }'
}

vi_state() { awk -F'\t' -v k="$2" '$1 == k { print $2; exit }' "$1" 2>/dev/null; }

# The same journal the installer keeps; an install that did not finish is put back before anything is removed.
vi_tx_rollback() {
    vi_rb=0
    vi_rbk=
    awk '{ l[NR] = $0 } END { for (i = NR; i > 0; i--) print l[i] }' "$1" > "$1.rev" || return 1
    while IFS="$vi_tab" read -r vi_op vi_a vi_b; do
        case $vi_op in
            put)
                if [ "$vi_b" = - ]; then rm -f -- "$vi_a" || vi_rb=1
                elif [ -e "$vi_b" ] || [ -L "$vi_b" ]; then rm -f -- "$vi_a"; mv -f -- "$vi_b" "$vi_a" || vi_rb=1; fi ;;
            dir) rmdir -- "$vi_a" 2>/dev/null ;;
            backup) vi_rbk=$vi_a ;;
        esac
    done < "$1.rev"
    rm -f -- "$1.rev"
    [ "$vi_rb" = 0 ] || return 1
    [ -n "$vi_rbk" ] && rm -rf -- "$vi_rbk"
    rm -f -- "$1"
    return 0
}

vi_tx_recover() {
    [ -f "$1" ] || return 0
    if grep -qx commit "$1"; then
        vi_rbk=$(awk -F'\t' '$1 == "backup" { print $2; exit }' "$1")
        [ -n "$vi_rbk" ] && rm -rf -- "$vi_rbk"
        rm -f -- "$1"
        return 0
    fi
    vi_say "The last install of $2 did not finish; putting back what it changed first."
    vi_tx_rollback "$1"
}

vi_mimeapps_drop() {
    vi_f="$VI_CONFIG_HOME/mimeapps.list"
    [ -f "$vi_f" ] || return 0
    awk -v m="$1" -v d="$2" '
        /^\[/ { sec = $0 }
        sec == "[Default Applications]" && index($0, m "=") == 1 {
            n = split(substr($0, length(m) + 2), v, ";"); out = ""
            for (i = 1; i <= n; i++) if (v[i] != "" && v[i] != d) out = out v[i] ";"
            if (out != "") print m "=" out
            next
        }
        { print }' "$vi_f" > "$vi_f.vi-new" && mv -f -- "$vi_f.vi-new" "$vi_f"
}

vi_refresh_desktop() {
    command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database -q "$XDG_DATA_HOME/applications" 2>/dev/null
    command -v update-mime-database >/dev/null 2>&1 && [ -d "$XDG_DATA_HOME/mime/packages" ] && update-mime-database "$XDG_DATA_HOME/mime" >/dev/null 2>&1
    [ -d "$XDG_DATA_HOME/icons/hicolor" ] && touch "$XDG_DATA_HOME/icons/hicolor" 2>/dev/null
    return 0
}

# vi_remove ID: 0 when everything the record lists is gone.
vi_remove() {
    vi_rec="$VI_REG/$1.state"
    vi_name=$(vi_state "$vi_rec" name)
    vi_ver=$(vi_state "$vi_rec" version)
    vi_dir=$(vi_state "$vi_rec" installDir)
    [ -n "$vi_name" ] || vi_name=$1
    vi_l="$VI_REG/$1.lock"
    if ! mkdir "$vi_l" 2>/dev/null; then
        vi_pid=$(cat "$vi_l/pid" 2>/dev/null)
        if [ -n "$vi_pid" ] && kill -0 "$vi_pid" 2>/dev/null; then
            vi_warn "$vi_name is being installed right now (process $vi_pid); it was not removed."
            return 1
        fi
        rm -rf -- "$vi_l"
        mkdir "$vi_l" 2>/dev/null || { vi_warn "Could not take the lock $vi_l; $vi_name was not removed."; return 1; }
    fi
    VI_LOCKDIR=$vi_l
    echo $$ > "$vi_l/pid"
    vi_tx_recover "$VI_REG/$1.journal" "$vi_name" || { vi_warn "Could not put back the unfinished install of $vi_name; see $VI_REG/$1.journal."; return 1; }

    # another install that needs this one keeps working only until it next starts
    for vi_o in "$VI_REG"/*.state; do
        [ -f "$vi_o" ] || continue
        vi_oid=$(vi_state "$vi_o" id)
        [ "$vi_oid" = "$1" ] && continue
        case " $VI_REMOVING " in *" $vi_oid "*) continue ;; esac
        if awk -F'\t' -v r="$1" '$1 == "requires" && $2 == r { f = 1 } END { exit !f }' "$vi_o"; then
            vi_warn "$(vi_state "$vi_o" name) needs $vi_name, and will not start without it."
        fi
    done

    vi_bad=0
    awk -F'\t' '$1 == "assoc" && $4 == "1" { print $3 "\t" $5 }' "$vi_rec" > "$VI_TMP/defaults"
    while IFS="$vi_tab" read -r vi_mime vi_id; do vi_mimeapps_drop "$vi_mime" "$vi_id"; done < "$VI_TMP/defaults"
    awk -F'\t' '$1 == "file" { print $6 } $1 == "shortcut" { print $2 }' "$vi_rec" > "$VI_TMP/files"
    while IFS= read -r vi_p; do
        if [ -f "$vi_p" ] || [ -L "$vi_p" ]; then rm -f -- "$vi_p" || vi_bad=1; fi
    done < "$VI_TMP/files"
    # a link is removed only while it is still a link: something else may have been put there since
    awk -F'\t' '$1 == "link" { print $2 }' "$vi_rec" > "$VI_TMP/links"
    while IFS= read -r vi_p; do
        if [ -L "$vi_p" ]; then rm -f -- "$vi_p" || vi_bad=1; fi
    done < "$VI_TMP/links"
    awk -F'\t' '$1 == "archive" { print $5 }' "$vi_rec" > "$VI_TMP/dirs"
    [ -n "$vi_dir" ] && printf '%s\n' "$vi_dir" >> "$VI_TMP/dirs"
    [ -n "$vi_dir" ] && rm -f -- "$vi_dir/install-manifest.json"
    while IFS= read -r vi_d; do
        [ -d "$vi_d" ] && find "$vi_d" -depth -type d -empty -exec rmdir {} \; 2>/dev/null
    done < "$VI_TMP/dirs"
    rm -f -- "$VI_REG/$1.json" "$VI_REG/$1.home"
    if [ "$vi_bad" = 0 ]; then rm -f -- "$vi_rec"; fi
    rm -rf -- "$vi_l"
    VI_LOCKDIR=
    if [ "$vi_bad" = 0 ]; then
        vi_say "Removed $vi_name $vi_ver${vi_dir:+ from $vi_dir}."
        [ -n "$vi_dir" ] && [ -d "$vi_dir" ] && vi_say "    $vi_dir still has files that were not installed; they were left alone."
        return 0
    fi
    vi_warn "Some of $vi_name could not be removed; its record is kept, so running this again tries again."
    return 1
}

vi_main() {
    vi_list=0; vi_all=0; vi_yes=0; vi_only=
    while [ $# -gt 0 ]; do
        case $1 in
            --list|-List) vi_list=1 ;;
            --all|-All) vi_all=1 ;;
            --yes|-Yes|-y) vi_yes=1 ;;
            --id|-Id) shift; vi_only=${1:-} ;;
            *) vi_warn "Ignoring unknown argument: $1" ;;
        esac
        [ $# -gt 0 ] && shift
    done
    [ -n "${HOME:-}" ] || vi_die "HOME is not set."
    export XDG_DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
    VI_CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
    VI_REG=${INSTALL_REGISTRY_DIR:-}
    [ -n "$VI_REG" ] || VI_REG=$(vi_expand "$VI_REGISTRY_DIR")
    VI_TMP=$(mktemp -d "${TMPDIR:-/tmp}/vi-uninstall.XXXXXX") || vi_die "Cannot create a temporary folder."
    trap 'vi_cleanup; rm -rf -- "$VI_TMP"' EXIT
    trap 'exit 1' INT TERM HUP

    if [ "$vi_list" = 1 ]; then
        vi_any=0
        for vi_s in "$VI_REG"/*.state; do
            [ -f "$vi_s" ] || continue
            vi_any=1
            printf '%-24s %-14s %s\n' "$(vi_state "$vi_s" id)" "$(vi_state "$vi_s" version)" "$(vi_state "$vi_s" installDir)"
        done
        [ "$vi_any" = 1 ] || vi_say "Nothing is installed (no records in $VI_REG)."
        return 0
    fi

    VI_REMOVING=
    if [ "$vi_all" = 1 ]; then
        for vi_s in "$VI_REG"/*.state; do [ -f "$vi_s" ] && VI_REMOVING="$VI_REMOVING $(vi_state "$vi_s" id)"; done
    else
        VI_REMOVING=${vi_only:-$VI_ID}
        [ -f "$VI_REG/$VI_REMOVING.state" ] || vi_die "'$VI_REMOVING' is not installed (no record in $VI_REG). --list shows what is."
    fi
    [ -n "$VI_REMOVING" ] || { vi_say "Nothing is installed (no records in $VI_REG)."; return 0; }

    if [ "$vi_yes" = 0 ]; then
        vi_names=
        for vi_i in $VI_REMOVING; do vi_names="$vi_names${vi_names:+, }$(vi_state "$VI_REG/$vi_i.state" name) $(vi_state "$VI_REG/$vi_i.state" version)"; done
        # in a subshell: a redirection that fails on : ends a POSIX shell, not just the command
        if ! (: < /dev/tty) 2>/dev/null; then vi_die "Nothing to ask with; run it with --yes to remove $vi_names."; fi
        printf 'Remove %s? [y/N] ' "$vi_names" > /dev/tty
        read -r vi_answer < /dev/tty || vi_answer=
        case $vi_answer in y|Y|yes|Yes|YES) ;; *) vi_say "Nothing was removed."; return 0 ;; esac
    fi

    vi_failed=0
    for vi_i in $VI_REMOVING; do vi_remove "$vi_i" || vi_failed=1; done
    vi_refresh_desktop
    return "$vi_failed"
}

vi_main "$@"
